// slop-custom.js: Tap the Splat start / stop sound (from Slop lab, "Custom"; values as
// approved). Played by sounds.js through the same output as every other sound.

/**
 * Boomertanger splatter sound: "Custom"
 * A wet slop plop: a heavy low thump, a wet squelch with some bubbles, a short sticky pull, and cafeteria echo.
 * Duration: 1.68 s (playSlop returns this value).
 * Generated by Slop lab. Pure Web Audio: no dependencies, no audio files.
 *
 * Usage:
 *   import { playSlop } from './slop-custom.js';
 *   const sfx = ctx.createGain(); sfx.connect(ctx.destination); // your game's SFX bus
 *   logo.addEventListener('pointerdown', () => playSlop(ctx, sfx));
 */

const WEIGHT = 1.00;            // 0 to 1: how heavy the portion lands (deeper, louder thump)
const GOO = 0.40;               // 0 to 1: amount of wet bubbles and gloop in the squelch
const STICK = 0.33;             // 0 to 1: length of the sticky pull tail after impact
const PITCH_SEMITONES = -4;     // overall pitch shift in semitones; negative sounds bigger and grosser
const SPOON_KNOCK = false;      // true adds two metal spoon knocks on the tray after the plop
const ECHO = true;              // true adds a short cafeteria-room reverb
const VARY_EACH_TAP = false;    // true shifts pitch randomly by up to 1.5 semitones on every call

/**
 * Play the slop sound.
 * @param {BaseAudioContext} ctx  An existing (already unlocked) AudioContext, or an OfflineAudioContext.
 * @param {AudioNode} destination  Where to send the sound, e.g. your game's SFX gain node.
 * @param {number} [when]  Start time in the context's clock.
 * @returns {number} Duration of the sound in seconds.
 */
export function playSlop(ctx, destination, when = ctx.currentTime + 0.03) {
  return slopCore(ctx, destination, when, WEIGHT, GOO, STICK, PITCH_SEMITONES, SPOON_KNOCK, ECHO, VARY_EACH_TAP);
}

function slopCore(ctx, destination, when, WEIGHT, GOO, STICK, PITCH_SEMITONES, SPOON_KNOCK, ECHO, VARY_EACH_TAP) {
  var t = when;

  // Pitch multiplier: the base setting plus an optional per-call wobble
  var semis = PITCH_SEMITONES;
  if (VARY_EACH_TAP) semis += (Math.random() * 2 - 1) * 1.5;
  var pm = Math.pow(2, semis / 12);

  // Output chain: bus gain -> compressor -> destination
  var comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -12;
  comp.ratio.value = 4;
  comp.connect(destination);
  var bus = ctx.createGain();
  bus.gain.value = 0.85;
  bus.connect(comp);

  // Noise buffers: white (bright hiss) and brown (dark, wet rumble)
  function makeNoise(brown) {
    var len = ctx.sampleRate, b = ctx.createBuffer(1, len, ctx.sampleRate), d = b.getChannelData(0), last = 0;
    for (var i = 0; i < len; i++) {
      var w = Math.random() * 2 - 1;
      if (brown) { last = (last + 0.02 * w) / 1.02; d[i] = last * 3.5; }
      else d[i] = w;
    }
    return b;
  }
  var noiseW = makeNoise(false), noiseB = makeNoise(true);

  // Optional cafeteria echo: a convolver with a generated decaying-noise impulse
  if (ECHO) {
    var irLen = Math.floor(ctx.sampleRate * 1.1), ir = ctx.createBuffer(2, irLen, ctx.sampleRate);
    for (var ch = 0; ch < 2; ch++) {
      var id = ir.getChannelData(ch);
      for (var j = 0; j < irLen; j++) id[j] = (Math.random() * 2 - 1) * Math.pow(1 - j / irLen, 3);
    }
    var conv = ctx.createConvolver();
    conv.buffer = ir;
    var wetIn = ctx.createGain(); wetIn.gain.value = 0.45;
    var wet = ctx.createGain(); wet.gain.value = 0.6;
    bus.connect(wetIn); wetIn.connect(conv); conv.connect(wet); wet.connect(comp);
  }

  // ---- helpers ----
  function noiseSrc(brown, start, dur) {
    var s = ctx.createBufferSource();
    s.buffer = brown ? noiseB : noiseW;
    s.loop = true;
    s.start(start, Math.random() * 0.9);
    s.stop(start + dur + 0.05);
    return s;
  }
  function envG(g, start, peak, attack, decay) {
    g.gain.setValueAtTime(0.0001, start);
    g.gain.exponentialRampToValueAtTime(peak, start + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, start + attack + decay);
  }
  // A liquid "blip": a sine whose pitch rises quickly
  function bubble(start, f, amp, dur) {
    var o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(f, start);
    o.frequency.exponentialRampToValueAtTime(f * (1.8 + Math.random() * 1.2), start + dur);
    envG(g, start, amp, 0.004, dur);
    o.connect(g); g.connect(bus);
    o.start(start); o.stop(start + dur + 0.03);
  }
  // A tiny sticky click
  function crackle(start, f, amp) {
    var n = noiseSrc(false, start, 0.03), bp = ctx.createBiquadFilter(), g = ctx.createGain();
    bp.type = 'bandpass'; bp.frequency.value = f; bp.Q.value = 10;
    envG(g, start, amp, 0.002, 0.01 + Math.random() * 0.012);
    n.connect(bp); bp.connect(g); g.connect(bus);
  }

  // ---- layer 1: thump (the weight of the portion hitting the tray) ----
  (function () {
    var o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'sine';
    var f = (150 - WEIGHT * 70) * pm;
    o.frequency.setValueAtTime(f, t);
    o.frequency.exponentialRampToValueAtTime(f * 0.35, t + 0.16);
    envG(g, t, 0.5 + 0.6 * WEIGHT, 0.004, 0.18 + 0.2 * WEIGHT);
    o.connect(g); g.connect(bus);
    o.start(t); o.stop(t + 0.55);
    var n = noiseSrc(true, t, 0.35), lp = ctx.createBiquadFilter(), g2 = ctx.createGain();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(700 * pm, t);
    lp.frequency.exponentialRampToValueAtTime(180, t + 0.2);
    envG(g2, t, 0.5 + 0.7 * WEIGHT, 0.003, 0.12 + 0.12 * WEIGHT);
    n.connect(lp); lp.connect(g2); g2.connect(bus);
  })();

  // ---- layer 2: squelch (resonant wet body + bubbles) ----
  (function () {
    var s0 = t + 0.005, dur = 0.12 + GOO * 0.25;
    var n = noiseSrc(true, s0, dur + 0.12), bp = ctx.createBiquadFilter(), g = ctx.createGain();
    bp.type = 'bandpass';
    bp.Q.value = 3 + GOO * 12;
    bp.frequency.setValueAtTime(1100 * pm, s0 + 0.01);
    bp.frequency.exponentialRampToValueAtTime(260 * pm, s0 + dur);
    envG(g, s0, 0.9 + GOO * 0.8, 0.015, dur + 0.06);
    n.connect(bp); bp.connect(g); g.connect(bus);
    var count = Math.round(2 + GOO * 9);
    for (var i = 0; i < count; i++) {
      bubble(s0 + 0.02 + Math.random() * (0.06 + GOO * 0.3), (220 + Math.random() * 420) * pm,
        0.12 + Math.random() * 0.15, 0.035 + Math.random() * 0.05);
    }
  })();

  // ---- layer 3: sticky pull tail ----
  if (STICK >= 0.03) {
    var start = t + 0.1, sdur = 0.15 + STICK * 0.6;
    var sn = noiseSrc(false, start, sdur), sbp = ctx.createBiquadFilter(), sg = ctx.createGain();
    sbp.type = 'bandpass'; sbp.Q.value = 6;
    sbp.frequency.setValueAtTime(350 * pm, start);
    sbp.frequency.exponentialRampToValueAtTime(1500 * pm, start + sdur);
    sg.gain.setValueAtTime(0.0001, start);
    sg.gain.exponentialRampToValueAtTime(0.12 * STICK + 0.02, start + sdur * 0.4);
    sg.gain.exponentialRampToValueAtTime(0.0001, start + sdur);
    sn.connect(sbp); sbp.connect(sg); sg.connect(bus);
    var k = Math.round(STICK * 22);
    for (var q = 0; q < k; q++) crackle(start + Math.random() * sdur, (700 + Math.random() * 2500) * pm, 0.15 + Math.random() * 0.2);
    if (STICK > 0.35) bubble(start + sdur + 0.05, (700 + Math.random() * 300) * pm, 0.18, 0.05); // final drip
  }

  // ---- layer 4: spoon knocking twice on the tray edge ----
  if (SPOON_KNOCK) {
    var clank = function (start, vol) {
      var parts = [[1780, 0.22, 0.5], [2960, 0.16, 0.35], [4410, 0.1, 0.25], [5890, 0.07, 0.16]];
      var detune = 0.97 + Math.random() * 0.06;
      parts.forEach(function (p) {
        var o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'sine'; o.frequency.value = p[0] * detune;
        envG(g, start, p[1] * vol, 0.002, p[2]);
        o.connect(g); g.connect(bus);
        o.start(start); o.stop(start + p[2] + 0.03);
      });
      crackle(start, 5000, 0.3 * vol);
    };
    var c0 = t + 0.42 + STICK * 0.35;
    clank(c0, 1);
    clank(c0 + 0.17, 0.55);
  }

  var total = slopLength(GOO, STICK, SPOON_KNOCK, ECHO);

  // Free the output chain once the sound is done (live contexts only)
  if (typeof ctx.startRendering !== 'function') {
    setTimeout(function () {
      try { bus.disconnect(); comp.disconnect(); } catch (e) {}
    }, Math.max(0, (t + total - ctx.currentTime + 0.25) * 1000));
  }
  return total;
}

function slopLength(GOO, STICK, SPOON_KNOCK, ECHO) {
  // Seconds from the start time until the longest layer has finished
  var end = 0.55;                                                // low thump
  end = Math.max(end, 0.005 + 0.12 + GOO * 0.25 + 0.13);         // squelch body
  end = Math.max(end, 0.02 + 0.06 + GOO * 0.3 + 0.12);           // last bubble
  if (STICK >= 0.03) end = Math.max(end, 0.1 + 0.15 + STICK * 0.6 + 0.13); // sticky pull + drip
  if (SPOON_KNOCK) end = Math.max(end, 0.42 + STICK * 0.35 + 0.17 + 0.53); // second spoon knock
  if (ECHO) end += 1.1;                                          // reverb tail
  return Math.ceil(end * 100) / 100;
}
